from pathlib import Path
import re
p=Path('sua-giao-an/v60.html');s=p.read_text(encoding='utf-8')
for v in ('TIENG_ANH','TIN_HOC','MI_THUAT','AM_NHAC'):
    s=re.sub(r'<label><input class="subjectCheck" type="checkbox" value="'+v+r'">.*?</label>','',s,flags=re.S)
s=re.sub(r"TIENG_ANH:'Tiếng Anh',TIN_HOC:'Tin học',MI_THUAT:'Mĩ thuật',AM_NHAC:'Âm nhạc',",'',s)
for a,b in [('gemini-3.6-flash','gemini-3.7-flash'),('Gemini 3.6 Flash','Gemini 3.7 Flash'),('gemini-3.5-flash-lite','gemini-2.5-flash'),('Gemini 3.5 Flash-Lite','Gemini 2.5 Flash')]: s=s.replace(a,b)
s=s.replace('S.subjects.filter(x=>!ADMIN.has(x))','S.subjects')
s=s.replace("S.changes.forEach(c=>{if(counts[c.subject])counts[c.subject].found++});",'')
# Critical gate fix: Gemini must be available after a successful scan even when Rule Engine found 0 changes.
s=s.replace("$('gemReview').disabled=!(S.changes.length||S.integration.length);", "$('gemReview').disabled=!S.docs.length||!S.subjects.length;")
# Make the zero-change state explicit so the user can proceed to semantic review.
s=s.replace("out.innerHTML=S.integration.length?'Chưa có Change Set tích hợp; chạy Gemini.':'Chưa có Change Set.';", "out.innerHTML=S.integration.length?'Chưa có Change Set tích hợp; chạy Gemini.':'✅ Chưa có Rule Change Set; Gemini vẫn sẵn sàng để phân tích ngữ nghĩa toàn bộ môn đã chọn.';")
start=s.index('async function runGemini(prompt){');end=s.index('async function runGeminiWith(prompt){',start)
new_run=r'''function parseGeminiJSON(raw){const t=String(raw||'').trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();try{return JSON.parse(t)}catch{}const a=t.indexOf('{'),b=t.lastIndexOf('}');if(a>=0&&b>a)return JSON.parse(t.slice(a,b+1));throw Error('Gemini trả về JSON không hợp lệ.')}
async function runGemini(prompt){const k=$('gemKey').value.trim();if(!k)throw Error('Chưa nhập Gemini API Key.');const primary=$('gemModel').value,fallback=primary==='gemini-3.7-flash'?'gemini-2.5-flash':'gemini-3.7-flash';async function call(m){const r=await fetch('https://generativelanguage.googleapis.com/v1beta/models/'+encodeURIComponent(m)+':generateContent',{method:'POST',headers:{'Content-Type':'application/json','x-goog-api-key':k},body:JSON.stringify({contents:[{role:'user',parts:[{text:prompt}]}],generationConfig:{responseMimeType:'application/json',maxOutputTokens:7000}})}),raw=await r.text();if(!r.ok)throw Error('Gemini '+r.status+': '+raw.slice(0,900));const j=JSON.parse(raw),txt=j?.candidates?.[0]?.content?.parts?.map(x=>x.text||'').join('');if(!txt)throw Error('Gemini không trả nội dung.');return parseGeminiJSON(txt)}try{return await call(primary)}catch(e){if(/Gemini (429|500|502|503|504)/.test(e.message)&&fallback!==primary){$('gemStatus').textContent='🔄 '+primary+' không sẵn sàng → '+fallback+'...';return await call(fallback)}throw e}}
'''
s=s[:start]+new_run+s[end:]
start=s.index("$('gemReview').onclick=async()=>{");end=s.index("$('reset').onclick=()=>{",start)
new_review=r'''$('gemReview').onclick=async()=>{if(S.gemBusy)return;const k=$('gemKey').value.trim();if(!k){$('gemStatus').textContent='⚠️ Chưa có Gemini API Key.';return}if(!S.docs.length){$('gemStatus').textContent='⚠️ Chưa có giáo án.';return}if(!S.subjects.length){$('gemStatus').textContent='⚠️ Chưa chọn môn.';return}try{S.gemBusy=true;$('gemReview').disabled=true;$('gemStatus').textContent='⏳ Gemini đang rà soát đầy đủ '+S.subjects.length+' môn đã chọn...';const documents=S.docs.map(d=>({name:d.name,text:Object.values(d.parts).map(x=>pars(x).map(p=>p.text).join('\\n')).join('\\n')}));const prompt='Bạn là chuyên gia rà soát giáo án lớp 5 CTGDPT 2018, bộ Kết nối tri thức với cuộc sống. PHẢI rà soát toàn bộ các môn được chọn: '+S.subjects.map(x=>LABEL[x]).join(', ')+'. Mỗi môn phải có coverage. Địa giới hành chính chỉ áp dụng cho Đạo đức, Lịch sử - Địa lí, Toán, Tiếng Việt; các môn khác chỉ kiểm tra ngữ nghĩa/tích hợp. Không viết lại toàn bài, không xóa nội dung gốc, không đảo thứ tự. Kiểm tra YCCD, năng lực, phẩm chất, NLS, công dân số, Hồ Chí Minh, môi trường/BĐKH, nguồn nước, biển đảo, biên giới/chủ quyền, ATGT, đuối nước, quyền trẻ em, bình đẳng/hòa nhập, tài chính, STEM, pháp luật, sức khỏe, thiên tai, văn hóa/di sản, AI; phát hiện lỗi sao chép, sai đáp án, sai ngữ cảnh, ngày tháng. RULE ENGINE không lặp lại. Mỗi môn đã chọn PHẢI xuất hiện trong coverage. Nếu nội dung đã có: status=DA_CO, change=null. Nếu thiếu/có thể bổ sung: status=CO_THE_BO_SUNG và cung cấp change. Nếu nghi ngờ: status=CẦN_XÁC_MINH và change=null. Change phải có action REPLACE/INSERT_AFTER/DELETE, document đúng tên file, anchor ngắn nguyên văn duy nhất, replacement ngắn. Trả JSON: {summary,strengths[],coverage:[{subject,status,note}],gaps:[{id,subject,category,status,priority,reason,location,suggestion,change}]}. SELECTED_SUBJECTS='+JSON.stringify(S.subjects)+' EXISTING_RULE_IDS='+JSON.stringify(S.changes.map(x=>x.id))+' DOCUMENTS='+JSON.stringify(documents);const j=await runGemini(prompt);let added=0,blocked=0;const ids=new Set(S.changes.map(x=>x.id));const locate=(d,a)=>{if(!a)return null;for(const[part,x]of Object.entries(d.parts))for(const pp of pars(x)){const at=pp.text.indexOf(a);if(at>=0)return{part,paragraphIndex:pp.i,matchStart:at,matchLength:a.length}}return null};for(let i=0;i<(j.gaps||[]).length;i++){const g=j.gaps[i];if(!g||g.status==='DA_CO'||!S.subjects.includes(g.subject)||!g.change)continue;const c=g.change,d=S.docs.find(x=>x.name===(c.document||g.location));if(!d){blocked++;continue}const loc=locate(d,c.anchor);if(!loc){blocked++;continue}const id=g.id||'AI-'+String(i+1).padStart(3,'0');if(ids.has(id))continue;const action=String(c.action||'REPLACE').toUpperCase();if(!['REPLACE','INSERT_AFTER','DELETE'].includes(action)){blocked++;continue}S.changes.push({type:'AI',id,engine:'Gemini Semantic Review',subject:g.subject,status:g.status==='CẦN_XÁC_MINH'?'NEED_VERIFY':'PROPOSED',old_text:c.anchor,new_text:c.replacement||'',location:d.name,part:loc.part,paragraphIndex:loc.paragraphIndex,matchStart:loc.matchStart,matchLength:loc.matchLength,anchor:c.anchor,new:c.replacement||'',action,confidence:g.priority==='HIGH'?0.97:0.9,reason:g.reason||'Gemini phát hiện cần xử lý.',approved:false,rejected:false,applied:false,ui:''});ids.add(id);added++}const coverage=(j.coverage||[]).filter(x=>S.subjects.includes(x.subject)).map(x=>(LABEL[x.subject]||x.subject)+': '+x.status+(x.note?' — '+x.note:'')).join('\\n');$('report').textContent='🤖 Gemini: '+(j.summary||'Đã rà soát.')+'\\n\\n📚 Phạm vi: '+S.subjects.map(x=>LABEL[x]).join(', ')+'\\n\\n📌 Coverage:\\n'+(coverage||'Không nhận được coverage.')+'\\n\\n🧩 AI tạo '+added+' Change Set hợp lệ; '+blocked+' đề xuất bị chặn do không định vị được Anchor.';$('cc').textContent=S.changes.length;$('rr').textContent=S.changes.filter(c=>c.status==='REVIEW_REQUIRED'||c.status==='NEED_VERIFY').length;render();$('gemStatus').textContent='✅ Gemini đã rà soát toàn bộ môn đã chọn · thêm '+added+' Change Set hợp lệ.';step(5);audit('Gemini hoàn tất: '+S.subjects.map(x=>LABEL[x]).join(', '))}catch(e){$('gemStatus').textContent='❌ '+e.message}finally{S.gemBusy=false;$('gemReview').disabled=false}};
'''
s=s[:start]+new_review+s[end:]
s=s.replace('Checkbox nhiều môn · 4 môn địa giới riêng · Môn khác tích hợp riêng ·','Checkbox nhiều môn · quét đầy đủ mọi môn đã chọn · 4 môn địa giới riêng ·')
for bad in ('value="TIENG_ANH"','value="TIN_HOC"','value="MI_THUAT"','value="AM_NHAC"','gemini-3.6-flash','gemini-3.5-flash-lite'):
    if bad in s: raise SystemExit('SANITY_FAIL '+bad)
if s.count("$('gemReview').onclick=async()=>{")!=1: raise SystemExit('SANITY_FAIL gemReview')
if s.count('async function runGemini(prompt){')!=1: raise SystemExit('SANITY_FAIL runGemini')
if "$('gemReview').disabled=!(S.changes.length||S.integration.length);" in s: raise SystemExit('SANITY_FAIL review gate')
p.write_text(s,encoding='utf-8');print('PATCH_OK',len(s))
